  try { response = await fetch(new URL('sandbox', apiBase()), { method: 'POST', redirect: 'error', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(args || {}), signal: AbortSignal.timeout(60000) }); json = await response.json(); }
  catch { throw new Error('The sandbox service could not be reached'); }
  if (!response.ok) throw new Error(json?.error?.message || 'Sandbox creation failed');
  sandboxToken = json.data.credential.token;
  let stored = 'memory only';
  if (process.env.POLYACCOUNTS_TOKEN_FILE) { try { writeFileSync(process.env.POLYACCOUNTS_TOKEN_FILE, sandboxToken + '\n', { mode: 0o600 }); stored = process.env.POLYACCOUNTS_TOKEN_FILE; } catch { stored = 'memory only (token file not writable)'; } }
